program.compute:
options = read('/input/options')
ids = [row['id'] for row in options]
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for pick in combinations(ids, k):
        if valid(list(pick)):
            result = list(pick)
            break
    if result:
        break

program.effects:
if exists('/output/selection'):
    result = read('/output/selection')
else:
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

